/* libsomrando: C port of Moppu/SecretOfManaRandomizer v1.49 (commit 1404b7b).  LGPL-2.1 or later, see sr_core.h and COPYING.LIB.
 *
 * Nesoberi (Author: Moppleton), derived from SoMRandomizer/processing/hacks/openworld/Nesoberi.cs.  Translated to C 2026-10-18.
 * The images and the character table come from the build-time file generated by tools/gen_p4_hmisc_resources.py; a build without it refuses
 * the Open World mode (sr_p4_hmisc_supports) instead of writing a different ROM.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#include "sr_core.h"
#include "sr_p2_visual_color.h"
#include "sr_p4.h"
#include "sr_p4_hk_neso.h"

#define E(v) sr_emit(c, (v))
#define P(off, v) sr_poke(c, (off), (v))
#define TILESET16_OFFSETS 0xB4000

/* sr_p4_neso_data is defined by the file that tools/gen_p4_hmisc_resources.py generates at build time (every build links it). */

int sr_p4_hmisc_neso_available(void) { return sr_p4_neso_data.n_chars > 0 && sr_p4_neso_data.n_outfits > 0; }

/* SnesTile.WriteTile4bpp for the 8x8 area of a 16-pixel wide 8-bit image at (xpos, ypos) */
static void hmisc_write_tile(struct sr_ctx *c, const uint8_t *image, int xpos, int ypos, int address) {
  uint8_t enc[32];
  for (int b = 0; b < 32; b++) {
    enc[b] = 0;
    for (int bit = 0; bit < 8; bit++) {
      int y_loc = (b / 2) % 8;
      int bit_num = (b / 16) * 2 + (b % 2);
      if (image[(ypos + y_loc) * 16 + xpos + bit] & (1 << bit_num)) enc[b] |= (uint8_t)(1 << (7 - bit));
    }
  }
  for (int i = 0; i < 32; i++) P(address + i, enc[i]);
}

/* VanillaEventUtil.wordWrapText: tokens split on ' ' (empty ones included), 27 columns */
static char *hmisc_word_wrap(struct sr_ctx *c, const char *text) {
  size_t len = strlen(text);
  char *out = (char *)sr_alloc(c, len * 2 + 8);
  if (strchr(text, '\n')) {
    memcpy(out, text, len + 1);
    return out;
  }
  size_t o = 0;
  int width = 0;
  const char *p = text;
  for (;;) {
    const char *q = strchr(p, ' ');
    size_t tl = q ? (size_t)(q - p) : strlen(p);
    if ((int)tl + width >= 27) {
      out[o++] = '\n';
      width = 0;
    }
    memcpy(out + o, p, tl);
    o += tl;
    out[o++] = ' ';
    width += (int)tl + 1;
    if (!q) break;
    p = q + 1;
  }
  out[o] = 0;
  return out;
}

static void hmisc_check_ascii(struct sr_ctx *c, const char *s) {
  for (; *s; s++)
    if ((uint8_t)*s >= 0x80) sr_fail(c, SOMRANDO_ERR_UNSUPPORTED, "unsupported option: non-ASCII nesoberi hint text");
}

static void hmisc_add_dialogue(struct sr_ctx *c, struct sr_bytes *e, const char *text) {
  sr_event_text_bytes(c, e, text);
  sr_ev_sleep(c, e, 0);
}

int sr_p4_hack_nesoberi(struct sr_ctx *c) {
  if (!sr_p4_hmisc_neso_available()) sr_fail(c, SOMRANDO_ERR_UNSUPPORTED, "unsupported option: nesoberi resources are not built in");
  const struct sr_p4_neso_data *d = &sr_p4_neso_data;
  struct sr_random *r = &c->rc;

  const struct sr_p4_neso_char *birthday = NULL;
  time_t now = time(NULL);
  struct tm *lt = localtime(&now);
  int cur_month = lt ? lt->tm_mon + 1 : 0, cur_day = lt ? lt->tm_mday : 0;
#ifdef SOMRANDO_DEBUG
  const char *fake = getenv("SOMRANDO_FAKE_DATE");   /* "M-D", tests only */
  if (fake && sscanf(fake, "%d-%d", &cur_month, &cur_day) != 2) cur_month = cur_day = 0;
#endif
  for (int i = 0; i < d->n_chars; i++)
    if (d->chars[i].month == cur_month && d->chars[i].day == cur_day) {
      birthday = &d->chars[i];
      break;
    }

  /* even if it's a birthday, we roll one anyway, so not to change the rng. */
  const struct sr_p4_neso_char *neso = &d->chars[sr_random_next(r) % d->n_chars];
  if (birthday) neso = birthday;
  int outfit = neso->first_outfit + sr_random_next(r) % neso->n_outfits;
  const uint8_t *bmp = d->images[d->outfit_image[outfit]];

  /* generate palette and 8-bit image by searching for colors; presumes 15 or less unique colors used */
  int palette[24 * 16];
  int n_palette = 0;
  uint8_t *eight_bit = (uint8_t *)sr_alloc(c, 24 * 16);
  for (int y = 0; y < 24; y++) {
    for (int x = 0; x < 16; x++) {
      const uint8_t *px = bmp + (y * 16 + x) * 3;
      int c_int = px[0] + (px[1] << 8) + (px[2] << 16);
      int idx = -1;
      for (int k = 0; k < n_palette; k++)
        if (palette[k] == c_int) {
          idx = k;
          break;
        }
      if (idx < 0) {
        palette[n_palette] = c_int;
        idx = n_palette++;
      }
      eight_bit[y * 16 + x] = (uint8_t)idx;
    }
  }

  /* change things that use palette 4 to use palette 5 instead; the skull thing on the table gets palette 4 and becomes the nesoberi */
  uint8_t *tile_buf = (uint8_t *)sr_alloc(c, (size_t)sr_p4_hmisc_neso_buf_size());
  int tileset_len = sr_p4_hmisc_neso_tileset(c, tile_buf);
  sr_ensure_space_in_bank(&c->working_offset, tileset_len);
  int tileset_new_offset = c->working_offset;
  for (int i = 0; i < tileset_len; i++) E(tile_buf[i]);

  /* there's some space here for tilesets, use one */
  const int target_tileset16 = 33;
  for (int i = 0; i < 0x180; i++) P(0xb3580 + i, sr_peek(c, 0xb1a80 + i));
  /* file offsets instead of rom offsets for some reason here */
  P(TILESET16_OFFSETS + target_tileset16 * 3, tileset_new_offset);
  P(TILESET16_OFFSETS + target_tileset16 * 3 + 1, tileset_new_offset >> 8);
  P(TILESET16_OFFSETS + target_tileset16 * 3 + 2, tileset_new_offset >> 16);

  const int pal_start_offset = 0xC7FE0;
  const int src_pal_set = 86;
  const int pal_set = 90;
  for (int pal_num = 0; pal_num <= 7; pal_num++)
    for (int pal_index = 1; pal_index <= 15; pal_index++) {
      int o = pal_num * 30 + pal_index * 2;
      P(pal_start_offset + pal_set * 30 * 7 + o, sr_peek(c, pal_start_offset + src_pal_set * 30 * 7 + o));
      P(pal_start_offset + pal_set * 30 * 7 + o + 1, sr_peek(c, pal_start_offset + src_pal_set * 30 * 7 + o + 1));
    }
  P(0x8cac9, pal_set);
  P(0x8caca, 0x80 + target_tileset16);

  /* replace palette 4 in palette set 90 with the colors of the image */
  const int target_pal_num = 4;
  for (int i = 1; i < n_palette; i++) {
    struct sr_w2_color col = sr_w2_color_rgb(palette[i] & 0xFF, (palette[i] >> 8) & 0xFF, (palette[i] >> 16) & 0xFF);
    int off = pal_start_offset + pal_set * 30 * 7 + target_pal_num * 30 + i * 2;
    P(off, col.b[0]);
    P(off + 1, col.b[1]);
  }

  /* replace the images for the skull thing with a nesoberi; tile 2237 (4bpp, planar composite) */
  static const int tile_offsets[] = {0x1e17a0, 0x1e17c0, 0x1e19a0, 0x1e19c0, 0x1e1ba0, 0x1e1bc0};
  for (int i = 0; i < 6; i++) hmisc_write_tile(c, eight_bit, (i % 2) * 8, (i / 2) * 8, tile_offsets[i]);


    // ----------------------------------------------------------------------------------
    // remove animation on the skull thing that used to mirror the top part back and forth
    // ----------------------------------------------------------------------------------
    // 8069c->806a0
    // 2D C8 14 CD
    // replace with:
    P(0x8069c, 0x3D);
    P(0x8069d, 0x4F);
    P(0x8069e, 0x4D);
    P(0x8069f, 0x4F);

    // remove the nesoberi/skull thing in the ice palace before the boss
    // EDF2C, EDF3D, EDF41, EDF31, EDF44, EDF47
    P(0xEDF2C, 0x00);
    P(0xEDF3D, 0x00);
    P(0xEDF41, 0x00);
    P(0xEDF31, 0x00);
    P(0xEDF44, 0x00);
    P(0xEDF47, 0x00);

    // -------------------------------------------------------
    // event when you step next to it that says you patted it
    // -------------------------------------------------------
    // modify map data to have the trigger tile
    P(0xE1B41, 0x41);
    P(0xE1C10, 0x5E);
    P(0xE1C11, 0xC0);
    P(0xE1C12, 0xC2);
    // modify list of triggers to be in a different spot and have 6 items, including event 0x18B
    P(0x88FBE, 0xE0);
    P(0x88FBF, 0x01);
    P(0x88FC0, 0x2F);
    P(0x88FC1, 0x09);
    P(0x88FC2, 0x30);
    P(0x88FC3, 0x09);
    P(0x88FC4, 0x8B);
    P(0x88FC5, 0x01);
    P(0x88FC6, 0x2B);
    P(0x88FC7, 0x09);
    P(0x88FC8, 0x2B);
    P(0x88FC9, 0x09);
    // move it
    P(0x84264, 0xBE);
    P(0x84265, 0x8F);

  struct sr_bytes *ev = sr_event_new(c, 0x18B);
  const char *an = "a";
  if (strchr("AEIOU", neso->name[0])) an = "an";
  char line[160];
  snprintf(line, sizeof line, "It's %s %s nesoberi plush.", an, neso->name);
  sr_bytes_push(c, ev, EV_OPEN_DIALOGUE);
  hmisc_add_dialogue(c, ev, hmisc_word_wrap(c, line));
  sr_bytes_push(c, ev, 0x52);   /* CLEAR_DIALOGUE */
  hmisc_add_dialogue(c, ev, "You pat its head.");

  const int num_neso_hints = 3;
  char *names_copy = (char *)sr_alloc(c, strlen(neso->name) + 1);
  strcpy(names_copy, neso->name);
  const char *parts[4] = {0, 0, 0, 0};
  int n_parts = 0;
  for (char *tok = names_copy; n_parts < 4;) {
    parts[n_parts++] = tok;
    char *sp = strchr(tok, ' ');
    if (!sp) break;
    *sp = 0;
    tok = sp + 1;
  }
  const char *neso_firstname = parts[1];
  /* western names; swap */
  if (!strcmp(neso_firstname, "Taylor") || !strcmp(neso_firstname, "Verde")) neso_firstname = parts[0];
  /* yohane name has 3 words */
  if (!strcmp(neso_firstname, "Angel")) neso_firstname = parts[2];

  sr_ensure_space_in_bank(&c->working_offset, 30);


    /*
    * replace event opcode 0B, which isn't used, with a command to jump ahead by the given parameter
    * number of bytes in the current script, to avoid having to use multiple events for event logic.
    * This allows the neso to give a bunch of different hints without jumping to different events
    * to do so.
      C1/EAA3:    C220        REP #$20
      C1/EAA5:    AD0E01      LDA $010E
    */
    P(0x1EAA3, 0x22);
    P(0x1EAA4, (uint8_t)(c->working_offset));
    P(0x1EAA5, (uint8_t)(c->working_offset >> 8));
    P(0x1EAA6, (uint8_t)((c->working_offset >> 16) + 0xC0));
    P(0x1EAA7, 0x60); // RTS after

    // 16bit A
    E(0xC2);
    E(0x20);
    // inc $D1 - cmd itself
    E(0xE6);
    E(0xD1);
    // LDA $[D1]
    E(0xA7);
    E(0xD1);
    // AND #00FF
    E(0x29);
    E(0xFF);
    E(0x00);
    // CLC
    E(0x18);
    // ADC $D1
    E(0x65);
    E(0xD1);
    // STA $D1
    E(0x85);
    E(0xD1);
    // inc $D1 - param
    E(0xE6);
    E(0xD1);
    // RTL
    E(0x6B);
    // ^ so now events should be able to do 0B [xx] to skip ahead xx bytes after the end of the command

  /* Neso will only give hints for stuff if you haven't gotten them already, and uses these flags to determine that */
  static const struct { const char *name; uint8_t flag; } event_flags[] = {
    {"undine spells", 0xA9}, {"gnome spells", 0xA8}, {"sylphid spells", 0xAB}, {"salamando spells", 0xAA},
    {"lumina spells", 0xAC}, {"shade spells", 0xAD}, {"luna spells", 0xAE}, {"dryad spells", 0xAF},
    {"boy", 0x0C}, {"girl", 0x0D}, {"sprite", 0x0E}, {"axe", 0xCA}, {"sword", 0xC9}, {"whip", 0xCC},
    {"water seed", 0x90}, {"earth seed", 0x91}, {"wind seed", 0x92}, {"fire seed", 0x93},
    {"light seed", 0x94}, {"dark seed", 0x95}, {"moon seed", 0x96}, {"dryad seed", 0x97},
    {"moogle belt", 0x74}, {"midge mallet", 0x5C},
  };

  sr_bytes_push(c, ev, 0x52);   /* CLEAR_DIALOGUE */

#ifdef SOMRANDO_DEBUG
  {
    /* tests only: "prize|hint;prize|hint;..." replaces the hints published by OpenWorldHints */
    const char *fh = getenv("SOMRANDO_FAKE_HINTS");
    char key[24];
    for (int q = 0; fh && *fh && q < num_neso_hints; q++) {
      const char *bar = strchr(fh, '|'), *semi = bar ? strchr(bar, ';') : NULL;
      if (!bar) break;
      size_t pl = (size_t)(bar - fh), hl2 = semi ? (size_t)(semi - bar - 1) : strlen(bar + 1);
      char *pz = (char *)sr_alloc(c, pl + 1), *hz = (char *)sr_alloc(c, hl2 + 1);
      memcpy(pz, fh, pl);
      memcpy(hz, bar + 1, hl2);
      snprintf(key, sizeof key, "nesoPrize%d", q);
      sr_work_set(c, key, pz);
      snprintf(key, sizeof key, "nesoHint%d", q);
      sr_work_set(c, key, hz);
      fh = semi ? semi + 1 : "";
    }
  }
#endif

  for (int i = 0; i < num_neso_hints; i++) {
    char key[24];
    snprintf(key, sizeof key, "nesoPrize%d", i);
    const char *hint_item = sr_work_get(c, key);
    snprintf(key, sizeof key, "nesoHint%d", i);
    const char *hint_text = sr_work_get(c, key);
    if (!hint_item) hint_item = "";
    if (!hint_text) hint_text = "";
    hmisc_check_ascii(c, hint_item);
    hmisc_check_ascii(c, hint_text);
    uint8_t event_flag = 0x00;
    for (size_t k = 0; k < sizeof event_flags / sizeof *event_flags; k++)
      if (!strcmp(event_flags[k].name, hint_item)) event_flag = event_flags[k].flag;
    size_t hl = strlen(neso_firstname) + strlen(hint_item) + strlen(hint_text) + 32;
    char *neso_hint = (char *)sr_alloc(c, hl);
    snprintf(neso_hint, hl, "%s neso says: find %s %s", neso_firstname, hint_item, hint_text);
    char *headpat = hmisc_word_wrap(c, neso_hint);
    struct sr_bytes tmp = {0, 0, 0};
    sr_event_text_bytes(c, &tmp, headpat);
    int dialogue_skip_count = (int)tmp.len + 4;
    /* event logic to skip ahead if we've already gotten it */
    const uint8_t jump_ahead[2] = {0x0B, (uint8_t)dialogue_skip_count};
    sr_ev_logic(c, ev, event_flag, 0x1, 0xF, jump_ahead);
    hmisc_add_dialogue(c, ev, headpat);   /* if we didn't skip, give the hint */
    sr_bytes_push(c, ev, EV_CLOSE_DIALOGUE);
    sr_ev_end(c, ev);
  }
  /* skipped all */
  snprintf(line, sizeof line, "%s neso has no more hints for you.", neso_firstname);
  hmisc_add_dialogue(c, ev, hmisc_word_wrap(c, line));
  sr_bytes_push(c, ev, EV_CLOSE_DIALOGUE);
  sr_ev_end(c, ev);

  /* replace snowman with happy kanon snow neso (palette set 49, pal 1); colors of the image -> snowman palette index */
  static const struct { uint8_t r, g, b; } snow_colors[] = {
    {26, 187, 109}, {248, 248, 248}, {232, 240, 248}, {216, 216, 248}, {192, 184, 232}, {184, 168, 208}, {152, 136, 192},
  };
  uint8_t *snow_img = (uint8_t *)sr_alloc(c, 24 * 16);
  for (int i = 0; i < 24 * 16; i++) {
    const uint8_t *px = d->snow + i * 3;
    int found = -1;
    for (int k = 0; k < 7; k++)
      if (snow_colors[k].r == px[0] && snow_colors[k].g == px[1] && snow_colors[k].b == px[2]) found = k;
    if (found < 0) sr_fail(c, SOMRANDO_ERR_FAILED, "The given key was not present in the dictionary.");
    snow_img[i] = (uint8_t)found;
  }
  static const int snow_tile_offsets[] = {0x1f42a0, 0x1f42c0, 0x1f42e0, 0x1f5100, 0x1f5120, 0x1f5140};
  for (int i = 0; i < 6; i++) hmisc_write_tile(c, snow_img, (i % 2) * 8, (i / 2) * 8, snow_tile_offsets[i]);
  return 1;
}
